import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository; // fake repository

    @InjectMocks
    private OrderService orderService; // real service under test

    @Test
    void shouldCalculateTotalForValidOrder() {
        var mockOrder = new Order(1L, "Laptop", 999.99);
        when(orderRepository.findById(1L)).thenReturn(Optional.of(mockOrder)); // stub behavior

        var total = orderService.calculateTotal(1L);

        assertEquals(999.99, total); // assert on service logic
        verify(orderRepository).findById(1L); // verify interaction happened
    }
}

