import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class) // activates Mockito annotations
class CustomerServiceTest {
    @Mock
    private CustomerRepository customerRepository; // Mockito creates a mock

    @InjectMocks
    private CustomerService customerService; // Mockito injects the mock into this real object

    @Test
    void shouldFindCustomerByEmail() {
        var customer = new Customer(1L, "alice@example.com");
        when(customerRepository.findByEmail("alice@example.com")).thenReturn(Optional.of(customer));

        var result = customerService.getCustomerByEmail("alice@example.com");

        assertTrue(result.isPresent());
        verify(customerRepository).findByEmail("alice@example.com");
    }
}
